231	/// substitute_date -- ersetzt jedes ${date}-Token in einem <output>-Pfad durch das aktuelle Datum (YYYYMMDD).
232	/// Erlaubt den in der Golden-Instanz genutzten _runs/${date}/... -Pfad ohne externe Shell-Expansion.
233	[[nodiscard]] inline std::string substitute_date(std::string path) {
234	    constexpr std::string_view token = "${date}";
235	    if (path.find(token) == std::string::npos) { return path; }
236	    std::time_t const now = std::time(nullptr);
237	    std::tm           tm{};
238	#if defined(_WIN32)
239	    localtime_s(&tm, &now);
240	#else
241	    localtime_r(&now, &tm);
242	#endif
243	    char buf[16] = {};
244	    std::strftime(buf, sizeof(buf), "%Y%m%d", &tm);
245	    for (auto p = path.find(token); p != std::string::npos; p = path.find(token, p)) {
246	        path.replace(p, token.size(), buf);
247	    }
248	    return path;
249	}
