251	/// execute_messreihe -- der OFFIZIELLE Einstieg (INC-G+H): parse (INC-D) -> validate (INC-D) -> Antrieb
252	/// (run_experiment_profile) -> Export (INC-H: CSV + TikZ nach <output>). Rueckgabe int (Test-Kompat):
253	///   0 = ok · 2 = parse-Fehler · 3 = validate-Fehler · 4 = leerer Report · 5 = Export-Fehler.
254	/// registry_dir wird leer gelassen (rein strukturelle Validierung); der volle Registry-Abgleich (4)+(5) ist
255	/// Sache der Fassade, die das Registry-Verzeichnis kennt (analog test_experiment_parser::make_registry_dir).
256	[[nodiscard]] inline int execute_messreihe(std::string_view config_xml, std::string_view mode = "defined") {
257	    cx::XmlConfigParser const parser;
258	    auto const                profile = parser.parse_experiment_profile(std::filesystem::path{std::string{config_xml}});
259	    if (!profile) {
260	        std::cerr << "[INC-G] parse_experiment_profile fehlgeschlagen: " << config_xml << "\n";
261	        return 2;
262	    }
263	
264	    auto const vr = tlz::validate_experiment_profile(*profile); // registry_dir leer -> strukturelle Validierung
265	    if (!vr.ok) {
266	        std::cerr << "[INC-G] validate_experiment_profile: " << vr.errors.size() << " Fehler.\n";
267	        for (auto const& e : vr.errors) { std::cerr << "  [FEHLER] " << e << "\n"; }
268	        return 3;
269	    }
270	
271	    MessreiheReport const report = run_experiment_profile(*profile, parse_enumeration_mode(mode));
272	    if (report.outcomes.empty()) {
273	        std::cerr << "[INC-G] leerer MessreiheReport (keine Permutation getrieben).\n";
274	        return 4;
275	    }
276	
277	    // INC-H: Export CSV + TikZ nach den <output>-Pfaden der Experiment-XML (${date} aufgeloest, Parent-Dirs
278	    // angelegt). Der <binary_path> wird bewusst NICHT geschrieben -- der MessreiheReportExporter emittiert
279	    // ausschliesslich CSV + TikZ; der binaere Mess-Record-Pfad ist Sache des Voll-Pipeline-Writers (nicht INC-H).
280	    MessreiheReportExporter const ex;
281	    std::filesystem::path const   csv_path = substitute_date(profile->output.csv_path);
282	    std::filesystem::path const   tex_path = substitute_date(profile->output.latex_path);
283	
284	    std::error_code ec;
285	    if (csv_path.has_parent_path()) { std::filesystem::create_directories(csv_path.parent_path(), ec); }
286	    if (tex_path.has_parent_path()) { std::filesystem::create_directories(tex_path.parent_path(), ec); }
287	
288	    auto const cs = ex.write_csv(report, csv_path);
289	    auto const ts = ex.write_tikz_summary(report, tex_path);
290	    if (!cs.ok() || !ts.ok()) {
291	        std::cerr << "[INC-H] Export-Fehler: csv=" << cs.message << " tikz=" << ts.message << "\n";
292	        return 5;
293	    }
294	
295	    std::cout << "[INC-G+H] execute_messreihe ok: " << report.outcomes.size() << " Permutationen -> "
296	              << csv_path.string() << " + " << tex_path.string() << "\n";
297	    return 0;
298	}
